INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 122:1', 'Yo me alegré con los que me decían: A la casa de Jehová iremos.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 10:24-25', 'Y considerémonos unos a otros para estimularnos al amor y a las buenas obras; no dejando de congregarnos, como algunos tienen por costumbre, sino exhortándonos; y tanto más, cuanto veis que aquel día se acerca.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 18:20', 'Porque donde están dos o tres congregados en mi nombre, allí estoy yo en medio de ellos.', 'congregarse,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 2:42', 'Y perseveraban en la doctrina de los apóstoles, en la comunión unos con otros, en el partimiento del pan y en las oraciones.', 'congregarse,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 2:46-47', 'Y perseverando unánimes cada día en el templo, y partiendo el pan en las casas, comían juntos con alegría y sencillez de corazón, alabando a Dios, y teniendo favor con todo el pueblo. Y el Señor añadía cada día a la iglesia los que habían de ser salvos.', 'congregarse,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 84:10', 'Porque mejor es un día en tus atrios que mil fuera de ellos. Escogería antes estar a la puerta de la casa de mi Dios, que habitar en las moradas de maldad.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 84:1-2', '¡Cuán amables son tus moradas, oh Jehová de los ejércitos! Anhela mi alma y aun ardientemente desea los atrios de Jehová; mi corazón y mi carne cantan al Dios vivo.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 84:4', 'Bienaventurados los que habitan en tu casa; perpetuamente te alabarán.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 92:13', 'Plantados en la casa de Jehová, en los atrios de nuestro Dios florecerán.', 'congregarse,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 27:4', 'Una cosa he demandado a Jehová, ésta buscaré; que esté yo en la casa de Jehová todos los días de mi vida, para contemplar la hermosura de Jehová, y para inquirir en su templo.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 100:4', 'Entrad por sus puertas con acción de gracias, por sus atrios con alabanza; alabadle, bendecid su nombre.', 'congregarse,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 133:1', '¡Mirad cuán bueno y cuán delicioso es habitar los hermanos juntos en armonía!', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 23:6', 'Ciertamente el bien y la misericordia me seguirán todos los días de mi vida, y en la casa de Jehová moraré por largos días.', 'congregarse,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 26:8', 'Jehová, la habitación de tu casa he amado, y el lugar de la morada de tu gloria.', 'congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 65:4', 'Bienaventurado el que tú escogieres y atrajeres a ti, para que habite en tus atrios; seremos saciados del bien de tu casa, de tu santo templo.', 'congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 95:6', 'Venid, adoremos y postrémonos; arrodillémonos delante de Jehová nuestro Hacedor.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 96:8-9', 'Dad a Jehová la honra debida a su nombre; traed ofrendas, y venid a sus atrios. Adorad a Jehová en la hermosura de la santidad; temed delante de él, toda la tierra.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 116:18-19', 'A Jehová pagaré ahora mis votos delante de todo su pueblo, en los atrios de la casa de Jehová, en medio de ti, oh Jerusalén. Aleluya.', 'congregarse,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 35:18', 'Te confesaré en grande congregación; te alabaré entre numeroso pueblo.', 'congregarse,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 111:1', 'Alabaré a Jehová con todo el corazón en la compañía y congregación de los rectos.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 5:7', 'Mas yo por la abundancia de tu misericordia entraré en tu casa; adoraré hacia tu santo templo en tu temor.', 'congregarse,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 42:4', 'Me acuerdo de estas cosas, y derramo mi alma dentro de mí; de cómo yo fui con la multitud, y la conduje hasta la casa de Dios, entre voces de alegría y de alabanza del pueblo en fiesta.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 55:14', 'Que juntos comunicábamos dulcemente los secretos, y andábamos en amistad en la casa de Dios.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 2:3', 'Y vendrán muchos pueblos, y dirán: Venid, y subamos al monte de Jehová, a la casa del Dios de Jacob; y nos enseñará sus caminos, y caminaremos por sus sendas. Porque de Sion saldrá la ley, y de Jerusalén la palabra de Jehová.', 'congregarse,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 56:7', 'Yo los llevaré a mi santo monte, y los recrearé en mi casa de oración; sus holocaustos y sus sacrificios serán aceptos sobre mi altar; porque mi casa será llamada casa de oración para todos los pueblos.', 'congregarse,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 4:16', 'Vino a Nazaret, donde se había criado; y en el día de reposo entró en la sinagoga, conforme a su costumbre, y se levantó a leer.', 'congregarse,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 2:37', 'Y era viuda hacía ochenta y cuatro años; y no se apartaba del templo, sirviendo de noche y de día con ayunos y oraciones.', 'congregarse,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 1:14', 'Todos éstos perseveraban unánimes en oración y ruego, con las mujeres, y con María la madre de Jesús, y con sus hermanos.', 'congregarse,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 4:32', 'Y la multitud de los que habían creído era de un corazón y un alma; y ninguno decía ser suyo propio nada de lo que poseía, sino que tenían todas las cosas en común.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 12:27', 'Vosotros, pues, sois el cuerpo de Cristo, y miembros cada uno en particular.', 'congregarse,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:4-5', 'Porque de la manera que en un cuerpo tenemos muchos miembros, pero no todos los miembros tienen la misma función, así nosotros, siendo muchos, somos un cuerpo en Cristo, y todos miembros los unos de los otros.', 'congregarse,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 4:15-16', 'Sino que siguiendo la verdad en amor, crezcamos en todo en aquel que es la cabeza, esto es, Cristo, de quien todo el cuerpo, bien concertado y unido entre sí por todas las coyunturas que se ayudan mutuamente, según la actividad propia de cada miembro, recibe su crecimiento para ir edificándose en amor.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 2:19', 'Así que ya no sois extranjeros ni advenedizos, sino conciudadanos de los santos, y miembros de la familia de Dios.', 'congregarse,familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 2:21-22', 'En quien todo el edificio, bien coordinado, va creciendo para ser un templo santo en el Señor; en quien vosotros también sois juntamente edificados para morada de Dios en el Espíritu.', 'congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:16', 'La palabra de Cristo more en abundancia en vosotros, enseñándoos y exhortándoos unos a otros en toda sabiduría, cantando con gracia en vuestros corazones al Señor con salmos e himnos y cánticos espirituales.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 5:19-20', 'Hablando entre vosotros con salmos, con himnos y cánticos espirituales, cantando y alabando al Señor en vuestros corazones; dando siempre gracias por todo al Dios y Padre, en el nombre de nuestro Señor Jesucristo.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Tesalonicenses 5:11', 'Por lo cual, animaos unos a otros, y edificaos unos a otros, así como lo hacéis.', 'congregarse,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 3:13', 'Antes exhortaos los unos a los otros cada día, entre tanto que se dice: Hoy; para que ninguno de vosotros se endurezca por el engaño del pecado.', 'congregarse,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 1:7', 'Pero si andamos en luz, como él está en luz, tenemos comunión unos con otros, y la sangre de Jesucristo su Hijo nos limpia de todo pecado.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 16:18', 'Y yo también te digo, que tú eres Pedro, y sobre esta roca edificaré mi iglesia; y las puertas del Hades no prevalecerán contra ella.', 'congregarse,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 2:5', 'Vosotros también, como piedras vivas, sed edificados como casa espiritual y sacerdocio santo, para ofrecer sacrificios espirituales aceptables a Dios por medio de Jesucristo.', 'congregarse,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Eclesiastés 4:9-10', 'Mejores son dos que uno; porque tienen mejor paga de su trabajo. Porque si cayeren, el uno levantará a su compañero; pero ¡ay del solo! que cuando cayere, no habrá segundo que lo levante.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Eclesiastés 4:12', 'Y si alguno prevaleciere contra uno, dos le resistirán; y cordón de tres dobleces no se rompe pronto.', 'congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 13:35', 'En esto conocerán todos que sois mis discípulos, si tuviereis amor los unos con los otros.', 'congregarse,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:3', 'Engrandeced a Jehová conmigo, y exaltemos a una su nombre.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 118:24', 'Este es el día que hizo Jehová; nos gozaremos y alegraremos en él.', 'congregarse,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 24:52-53', 'Ellos, después de haberle adorado, volvieron a Jerusalén con gran gozo; y estaban siempre en el templo, alabando y bendiciendo a Dios. Amén.', 'congregarse,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Crónicas 7:15-16', 'Ahora estarán abiertos mis ojos y atentos mis oídos a la oración en este lugar; porque ahora he elegido y santificado esta casa, para que esté en ella mi nombre para siempre; y mis ojos y mi corazón estarán ahí para siempre.', 'congregarse,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Malaquías 3:16', 'Entonces los que temían a Jehová hablaron cada uno a su compañero; y Jehová escuchó y oyó, y fue escrito libro de memoria delante de él para los que temen a Jehová, y para los que piensan en su nombre.', 'congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 20:7', 'El primer día de la semana, reunidos los discípulos para partir el pan, Pablo les enseñaba, habiendo de salir al día siguiente; y alargó el discurso hasta la medianoche.', 'congregarse,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 14:26', '¿Qué hay, pues, hermanos? Cuando os reunís, cada uno de vosotros tiene salmo, tiene doctrina, tiene lengua, tiene revelación, tiene interpretación. Hágase todo para edificación.', 'congregarse,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 68:6', 'Dios hace habitar en familia a los desamparados; saca a los cautivos a prosperidad; mas los rebeldes habitan en tierra seca.', 'familia,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 11:1', 'Es, pues, la fe la certeza de lo que se espera, la convicción de lo que no se ve.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 11:6', 'Pero sin fe es imposible agradar a Dios; porque es necesario que el que se acerca a Dios crea que le hay, y que es galardonador de los que le buscan.', 'fe,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 12:2', 'Puestos los ojos en Jesús, el autor y consumador de la fe, el cual por el gozo puesto delante de él sufrió la cruz, menospreciando el oprobio, y se sentó a la diestra del trono de Dios.', 'fe,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 9:23', 'Jesús le dijo: Si puedes creer, al que cree todo le es posible.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 11:24', 'Por tanto, os digo que todo lo que pidiereis orando, creed que lo recibiréis, y os vendrá.', 'fe,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 10:17', 'Así que la fe es por el oír, y el oír, por la palabra de Dios.', 'fe,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 5:1', 'Justificados, pues, por la fe, tenemos paz para con Dios por medio de nuestro Señor Jesucristo.', 'fe,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 2:8-9', 'Porque por gracia sois salvos por medio de la fe; y esto no de vosotros, pues es don de Dios; no por obras, para que nadie se gloríe.', 'fe,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Gálatas 2:20', 'Con Cristo estoy juntamente crucificado, y ya no vivo yo, mas vive Cristo en mí; y lo que ahora vivo en la carne, lo vivo en la fe del Hijo de Dios, el cual me amó y se entregó a sí mismo por mí.', 'fe,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 5:7', 'Porque por fe andamos, no por vista.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 17:20', 'Jesús les dijo: Por vuestra poca fe; porque de cierto os digo, que si tuviereis fe como un grano de mostaza, diréis a este monte: Pásate de aquí allá, y se pasará; y nada os será imposible.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 1:37', 'Porque nada hay imposible para Dios.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 3:16', 'Porque de tal manera amó Dios al mundo, que ha dado a su Hijo unigénito, para que todo aquel que en él cree, no se pierda, mas tenga vida eterna.', 'fe,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 11:25-26', 'Le dijo Jesús: Yo soy la resurrección y la vida; el que cree en mí, aunque esté muerto, vivirá. Y todo aquel que vive y cree en mí, no morirá eternamente. ¿Crees esto?', 'fe,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 14:1', 'No se turbe vuestro corazón; creéis en Dios, creed también en mí.', 'fe,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 20:29', 'Jesús le dijo: Porque me has visto, Tomás, creíste; bienaventurados los que no vieron, y creyeron.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 1:16', 'Porque no me avergüenzo del evangelio, porque es poder de Dios para salvación a todo aquel que cree; al judío primeramente, y también al griego.', 'fe,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 5:4', 'Porque todo lo que es nacido de Dios vence al mundo; y esta es la victoria que ha vencido al mundo, nuestra fe.', 'fe,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 3:5-6', 'Fíate de Jehová de todo tu corazón, y no te apoyes en tu propia prudencia. Reconócelo en todos tus caminos, y él enderezará tus veredas.', 'fe,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 37:5', 'Encomienda a Jehová tu camino, y confía en él; y él hará.', 'fe,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Jeremías 17:7-8', 'Bendito el varón que confía en Jehová, y cuya confianza es Jehová. Porque será como el árbol plantado junto a las aguas, que junto a la corriente echará sus raíces, y no verá cuando viene el calor, sino que su hoja estará verde; y en el año de sequía no se fatigará, ni dejará de dar fruto.', 'fe,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 5:36', 'Pero Jesús, luego que oyó lo que se decía, dijo al principal de la sinagoga: No temas, cree solamente.', 'fe,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 10:23', 'Mantengamos firme, sin fluctuar, la profesión de nuestra esperanza, porque fiel es el que prometió.', 'fe,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 1:8', 'A quien amáis sin haberle visto, en quien creyendo, aunque ahora no lo veáis, os alegráis con gozo inefable y glorioso.', 'fe,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 4:20-21', 'Tampoco dudó, por incredulidad, de la promesa de Dios, sino que se fortaleció en fe, dando gloria a Dios, plenamente convencido de que era también poderoso para hacer todo lo que había prometido.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 6:35', 'Jesús les dijo: Yo soy el pan de vida; el que a mí viene, nunca tendrá hambre; y el que en mí cree, no tendrá sed jamás.', 'fe,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 8:12', 'Otra vez Jesús les habló, diciendo: Yo soy la luz del mundo; el que me sigue, no andará en tinieblas, sino que tendrá la luz de la vida.', 'fe,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 14:6', 'Jesús le dijo: Yo soy el camino, y la verdad, y la vida; nadie viene al Padre, sino por mí.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 16:31', 'Ellos dijeron: Cree en el Señor Jesucristo, y serás salvo, tú y tu casa.', 'fe,familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Timoteo 1:12', 'Por lo cual asimismo padezco esto; pero no me avergüenzo, porque yo sé a quién he creído, y estoy seguro que es poderoso para guardar mi depósito para aquel día.', 'fe,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 21:22', 'Y todo lo que pidiereis en oración, creyendo, lo recibiréis.', 'fe,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 10:27-28', 'Mis ovejas oyen mi voz, y yo las conozco, y me siguen, y yo les doy vida eterna; y no perecerán jamás, ni nadie las arrebatará de mi mano.', 'fe,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 15:5', 'Yo soy la vid, vosotros los pámpanos; el que permanece en mí, y yo en él, éste lleva mucho fruto; porque separados de mí nada podéis hacer.', 'fe,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 10:9', 'Que si confesares con tu boca que Jesús es el Señor, y creyeres en tu corazón que Dios le levantó de los muertos, serás salvo.', 'fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Josué 1:9', 'Mira que te mando que te esfuerces y seas valiente; no temas ni desmayes, porque Jehová tu Dios estará contigo en dondequiera que vayas.', 'animo,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 41:10', 'No temas, porque yo estoy contigo; no desmayes, porque yo soy tu Dios que te esfuerzo; siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.', 'animo,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 41:13', 'Porque yo Jehová soy tu Dios, quien te sostiene de tu mano derecha, y te dice: No temas, yo te ayudo.', 'animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Deuteronomio 31:6', 'Esforzaos y cobrad ánimo; no temáis, ni tengáis miedo de ellos, porque Jehová tu Dios es el que va contigo; no te dejará, ni te desamparará.', 'animo,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Deuteronomio 31:8', 'Y Jehová va delante de ti; él estará contigo, no te dejará, ni te desamparará; no temas ni te intimides.', 'animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 27:1', 'Jehová es mi luz y mi salvación; ¿de quién temeré? Jehová es la fortaleza de mi vida; ¿de quién he de atemorizarme?', 'animo,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 27:14', 'Aguarda a Jehová; esfuérzate, y aliéntese tu corazón; sí, espera a Jehová.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 31:24', 'Esforzaos todos vosotros los que esperáis en Jehová, y tome aliento vuestro corazón.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 42:11', '¿Por qué te abates, oh alma mía, y por qué te turbas dentro de mí? Espera en Dios; porque aún he de alabarle, salvación mía y Dios mío.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:18', 'Cercano está Jehová a los quebrantados de corazón; y salva a los contritos de espíritu.', 'animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 147:3', 'Él sana a los quebrantados de corazón, y venda sus heridas.', 'animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 30:5', 'Porque un momento será su ira, pero su favor dura toda la vida. Por la noche durará el lloro, y a la mañana vendrá la alegría.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 16:33', 'Estas cosas os he hablado para que en mí tengáis paz. En el mundo tendréis aflicción; pero confiad, yo he vencido al mundo.', 'animo,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 4:8-9', 'Que estamos atribulados en todo, mas no angustiados; en apuros, mas no desesperados; perseguidos, mas no desamparados; derribados, pero no destruidos.', 'animo,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 4:16-17', 'Por tanto, no desmayamos; antes aunque este nuestro hombre exterior se va desgastando, el interior no obstante se renueva de día en día. Porque esta leve tribulación momentánea produce en nosotros un cada vez más excelente y eterno peso de gloria.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:28', 'Y sabemos que a los que aman a Dios, todas las cosas les ayudan a bien, esto es, a los que conforme a su propósito son llamados.', 'animo,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:31', '¿Qué, pues, diremos a esto? Si Dios es por nosotros, ¿quién contra nosotros?', 'animo,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:37-39', 'Antes, en todas estas cosas somos más que vencedores por medio de aquel que nos amó. Por lo cual estoy seguro de que ni la muerte, ni la vida, ni ángeles, ni principados, ni potestades, ni lo presente, ni lo por venir, ni lo alto, ni lo profundo, ni ninguna otra cosa creada nos podrá separar del amor de Dios, que es en Cristo Jesús Señor nuestro.', 'animo,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 1:6', 'Estando persuadido de esto, que el que comenzó en vosotros la buena obra, la perfeccionará hasta el día de Jesucristo.', 'animo,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Gálatas 6:9', 'No nos cansemos, pues, de hacer bien; porque a su tiempo segaremos, si no desmayamos.', 'animo,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 15:58', 'Así que, hermanos míos amados, estad firmes y constantes, creciendo en la obra del Señor siempre, sabiendo que vuestro trabajo en el Señor no es en vano.', 'animo,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Sofonías 3:17', 'Jehová está en medio de ti, poderoso, él salvará; se gozará sobre ti con alegría, callará de amor, se regocijará sobre ti con cánticos.', 'animo,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 43:2', 'Cuando pases por las aguas, yo estaré contigo; y si por los ríos, no te anegarán. Cuando pases por el fuego, no te quemarás, ni la llama arderá en ti.', 'animo,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 43:1', 'Ahora, así dice Jehová, Creador tuyo, oh Jacob, y Formador tuyo, oh Israel: No temas, porque yo te redimí; te puse nombre, mío eres tú.', 'animo,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 55:22', 'Echa sobre Jehová tu carga, y él te sustentará; no dejará para siempre caído al justo.', 'animo,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 5:7', 'Echando toda vuestra ansiedad sobre él, porque él tiene cuidado de vosotros.', 'animo,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 11:28-30', 'Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar. Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas; porque mi yugo es fácil, y ligera mi carga.', 'animo,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:19', 'Muchas son las aflicciones del justo, pero de todas ellas le librará Jehová.', 'animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lamentaciones 3:22-23', 'Por la misericordia de Jehová no hemos sido consumidos, porque nunca decayeron sus misericordias. Nuevas son cada mañana; grande es tu fidelidad.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Miqueas 7:8', 'Tú, enemiga mía, no te alegres de mí, porque aunque caí, me levantaré; aunque more en tinieblas, Jehová será mi luz.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 3:3', 'Mas tú, Jehová, eres escudo alrededor de mí; mi gloria, y el que levanta mi cabeza.', 'animo,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 54:10', 'Porque los montes se moverán, y los collados temblarán, pero no se apartará de ti mi misericordia, ni el pacto de mi paz se quebrantará, dijo Jehová, el que tiene misericordia de ti.', 'animo,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Crónicas 15:7', 'Pero esforzaos vosotros, y no desfallezcan vuestras manos, pues hay recompensa para vuestra obra.', 'animo,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 13:5-6', 'Sean vuestras costumbres sin avaricia, contentos con lo que tenéis ahora; porque él dijo: No te desampararé, ni te dejaré; de manera que podemos decir confiadamente: El Señor es mi ayudador; no temeré lo que me pueda hacer el hombre.', 'animo,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 40:1-2', 'Pacientemente esperé a Jehová, y se inclinó a mí, y oyó mi clamor. Y me hizo sacar del pozo de la desesperación, del lodo cenagoso; puso mis pies sobre peña, y enderezó mis pasos.', 'animo,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 40:29', 'Él da esfuerzo al cansado, y multiplica las fuerzas al que no tiene ningunas.', 'fuerza,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 40:31', 'Pero los que esperan a Jehová tendrán nuevas fuerzas; levantarán alas como las águilas; correrán, y no se cansarán; caminarán, y no se fatigarán.', 'fuerza,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 4:13', 'Todo lo puedo en Cristo que me fortalece.', 'fuerza,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Nehemías 8:10', 'Luego les dijo: Id, comed grosuras, y bebed vino dulce, y enviad porciones a los que no tienen nada preparado; porque día santo es a nuestro Señor; no os entristezcáis, porque el gozo de Jehová es vuestra fuerza.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 46:1', 'Dios es nuestro amparo y fortaleza, nuestro pronto auxilio en las tribulaciones.', 'fuerza,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 18:2', 'Jehová, roca mía y castillo mío, y mi libertador; Dios mío, fortaleza mía, en él confiaré; mi escudo, y la fuerza de mi salvación, mi alto refugio.', 'fuerza,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 18:32', 'Dios es el que me ciñe de poder, y quien hace perfecto mi camino.', 'fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 28:7', 'Jehová es mi fortaleza y mi escudo; en él confió mi corazón, y fui ayudado, por lo que se gozó mi corazón, y con mi cántico le alabaré.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 73:26', 'Mi carne y mi corazón desfallecen; mas la roca de mi corazón y mi porción es Dios para siempre.', 'fuerza,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 121:1-2', 'Alzaré mis ojos a los montes; ¿de dónde vendrá mi socorro? Mi socorro viene de Jehová, que hizo los cielos y la tierra.', 'fuerza,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 29:11', 'Jehová dará poder a su pueblo; Jehová bendecirá a su pueblo con paz.', 'fuerza,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 6:10', 'Por lo demás, hermanos míos, fortaleceos en el Señor, y en el poder de su fuerza.', 'fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 12:9', 'Y me ha dicho: Bástate mi gracia; porque mi poder se perfecciona en la debilidad. Por tanto, de buena gana me gloriaré más bien en mis debilidades, para que repose sobre mí el poder de Cristo.', 'fuerza,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Timoteo 1:7', 'Porque no nos ha dado Dios espíritu de cobardía, sino de poder, de amor y de dominio propio.', 'fuerza,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Habacuc 3:19', 'Jehová el Señor es mi fortaleza, el cual hace mis pies como de ciervas, y en mis alturas me hace andar.', 'fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 12:2', 'He aquí Dios es salvación mía; me aseguraré y no temeré; porque mi fortaleza y mi canción es JAH Jehová, quien ha sido salvación para mí.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Éxodo 15:2', 'Jehová es mi fortaleza y mi cántico, y ha sido mi salvación. Este es mi Dios, y lo alabaré; Dios de mi padre, y lo enalteceré.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Zacarías 4:6', 'Entonces respondió y me habló diciendo: Esta es palabra de Jehová a Zorobabel, que dice: No con ejército, ni con fuerza, sino con mi Espíritu, ha dicho Jehová de los ejércitos.', 'fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 138:3', 'El día que clamé, me respondiste; me fortaleciste con vigor en mi alma.', 'fuerza,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Crónicas 16:11', 'Buscad a Jehová y su poder; buscad su rostro continuamente.', 'fuerza,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Deuteronomio 33:27', 'El eterno Dios es tu refugio, y acá abajo los brazos eternos; él echó de delante de ti al enemigo, y dijo: Destruye.', 'fuerza,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 59:16', 'Pero yo cantaré de tu poder, y alabaré de mañana tu misericordia; porque has sido mi amparo y refugio en el día de mi angustia.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 84:5', 'Bienaventurado el hombre que tiene en ti sus fuerzas, en cuyo corazón están tus caminos.', 'fuerza,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 3:16', 'Para que os dé, conforme a las riquezas de su gloria, el ser fortalecidos con poder en el hombre interior por su Espíritu.', 'fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 40:28', '¿No has sabido, no has oído que el Dios eterno es Jehová, el cual creó los confines de la tierra? No desfallece, ni se fatiga con cansancio, y su entendimiento no hay quien lo alcance.', 'fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 118:14', 'Mi fortaleza y mi cántico es JAH, y él me ha sido por salvación.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 1:11', 'Fortalecidos con todo poder, conforme a la potencia de su gloria, para toda paciencia y longanimidad; con gozo.', 'fuerza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 14:27', 'La paz os dejo, mi paz os doy; yo no os la doy como el mundo la da. No se turbe vuestro corazón, ni tenga miedo.', 'paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 4:6-7', 'Por nada estéis afanosos, sino sean conocidas vuestras peticiones delante de Dios en toda oración y ruego, con acción de gracias. Y la paz de Dios, que sobrepasa todo entendimiento, guardará vuestros corazones y vuestros pensamientos en Cristo Jesús.', 'paz,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 26:3', 'Tú guardarás en completa paz a aquel cuyo pensamiento en ti persevera; porque en ti ha confiado.', 'paz,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 4:8', 'En paz me acostaré, y asimismo dormiré; porque solo tú, Jehová, me haces vivir confiado.', 'paz,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 23:1-3', 'Jehová es mi pastor; nada me faltará. En lugares de delicados pastos me hará descansar; junto a aguas de reposo me pastoreará. Confortará mi alma; me guiará por sendas de justicia por amor de su nombre.', 'paz,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 23:4', 'Aunque ande en valle de sombra de muerte, no temeré mal alguno, porque tú estarás conmigo; tu vara y tu cayado me infundirán aliento.', 'paz,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Números 6:24-26', 'Jehová te bendiga, y te guarde; Jehová haga resplandecer su rostro sobre ti, y tenga de ti misericordia; Jehová alce sobre ti su rostro, y ponga en ti paz.', 'paz,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:15', 'Y la paz de Dios gobierne en vuestros corazones, a la que asimismo fuisteis llamados en un solo cuerpo; y sed agradecidos.', 'paz,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Tesalonicenses 3:16', 'Y el mismo Señor de paz os dé siempre paz en toda manera. El Señor sea con todos vosotros.', 'paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 85:8', 'Escucharé lo que hablará Jehová Dios; porque hablará paz a su pueblo y a sus santos, para que no se vuelvan a la locura.', 'paz,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 32:17', 'Y el efecto de la justicia será paz; y la labor de la justicia, reposo y seguridad para siempre.', 'paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 3:24', 'Cuando te acuestes, no tendrás temor, sino que te acostarás, y tu sueño será grato.', 'paz,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 37:11', 'Pero los mansos heredarán la tierra, y se recrearán con abundancia de paz.', 'paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 5:9', 'Bienaventurados los pacificadores, porque ellos serán llamados hijos de Dios.', 'paz,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:18', 'Si es posible, en cuanto dependa de vosotros, estad en paz con todos los hombres.', 'paz,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:165', 'Mucha paz tienen los que aman tu ley, y no hay para ellos tropiezo.', 'paz,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 9:6', 'Porque un niño nos es nacido, hijo nos es dado, y el principado sobre su hombro; y se llamará su nombre Admirable, Consejero, Dios Fuerte, Padre Eterno, Príncipe de Paz.', 'paz,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 116:7', 'Vuelve, oh alma mía, a tu reposo, porque Jehová te ha hecho bien.', 'paz,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 62:1', 'En Dios solamente está acallada mi alma; de él viene mi salvación.', 'paz,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 6:34', 'Así que, no os afanéis por el día de mañana, porque el día de mañana traerá su afán. Basta a cada día su propio mal.', 'paz,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 46:10', 'Estad quietos, y conoced que yo soy Dios; seré exaltado entre las naciones; enaltecido seré en la tierra.', 'paz,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 30:15', 'Porque así dijo Jehová el Señor, el Santo de Israel: En descanso y en reposo seréis salvos; en quietud y en confianza será vuestra fortaleza. Y no quisisteis.', 'paz,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Éxodo 14:14', 'Jehová peleará por vosotros, y vosotros estaréis tranquilos.', 'paz,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 94:19', 'En la multitud de mis pensamientos dentro de mí, tus consolaciones alegraban mi alma.', 'paz,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Josué 24:15', 'Y si mal os parece servir a Jehová, escogeos hoy a quién sirváis; si a los dioses a quienes sirvieron vuestros padres, cuando estuvieron al otro lado del río, o a los dioses de los amorreos en cuya tierra habitáis; pero yo y mi casa serviremos a Jehová.', 'familia,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 22:6', 'Instruye al niño en su camino, y aun cuando fuere viejo no se apartará de él.', 'familia,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 127:1', 'Si Jehová no edificare la casa, en vano trabajan los que la edifican; si Jehová no guardare la ciudad, en vano vela la guardia.', 'familia,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 127:3', 'He aquí, herencia de Jehová son los hijos; cosa de estima el fruto del vientre.', 'familia,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 128:1-3', 'Bienaventurado todo aquel que teme a Jehová, que anda en sus caminos. Cuando comieres el trabajo de tus manos, bienaventurado serás, y te irá bien. Tu mujer será como vid que lleva fruto a los lados de tu casa; tus hijos como plantas de olivo alrededor de tu mesa.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Deuteronomio 6:6-7', 'Y estas palabras que yo te mando hoy, estarán sobre tu corazón; y las repetirás a tus hijos, y hablarás de ellas estando en tu casa, y andando por el camino, y al acostarte, y cuando te levantes.', 'familia,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 6:1-3', 'Hijos, obedeced en el Señor a vuestros padres, porque esto es justo. Honra a tu padre y a tu madre, que es el primer mandamiento con promesa; para que te vaya bien, y seas de larga vida sobre la tierra.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 6:4', 'Y vosotros, padres, no provoquéis a ira a vuestros hijos, sino criadlos en disciplina y amonestación del Señor.', 'familia,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 5:25', 'Maridos, amad a vuestras mujeres, así como Cristo amó a la iglesia, y se entregó a sí mismo por ella.', 'familia,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 31:10', 'Mujer virtuosa, ¿quién la hallará? Porque su estima sobrepasa largamente a la de las piedras preciosas.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 31:30', 'Engañosa es la gracia, y vana la hermosura; la mujer que teme a Jehová, ésa será alabada.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 17:6', 'Corona de los viejos son los nietos, y la honra de los hijos, sus padres.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 103:17', 'Mas la misericordia de Jehová es desde la eternidad y hasta la eternidad sobre los que le temen, y su justicia sobre los hijos de los hijos.', 'familia,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 54:13', 'Y todos tus hijos serán enseñados por Jehová; y se multiplicará la paz de tus hijos.', 'familia,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 2:39', 'Porque para vosotros es la promesa, y para vuestros hijos, y para todos los que están lejos; para cuantos el Señor nuestro Dios llamare.', 'familia,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Génesis 2:24', 'Por tanto, dejará el hombre a su padre y a su madre, y se unirá a su mujer, y serán una sola carne.', 'familia,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Rut 1:16', 'Respondió Rut: No me ruegues que te deje, y me aparte de ti; porque a dondequiera que tú fueres, iré yo, y dondequiera que vivieres, viviré. Tu pueblo será mi pueblo, y tu Dios mi Dios.', 'familia,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 14:26', 'En el temor de Jehová está la fuerte confianza; y esperanza tendrán sus hijos.', 'familia,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 20:7', 'Camina en su integridad el justo; sus hijos son dichosos después de él.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('3 Juan 1:4', 'No tengo yo mayor gozo que este, el oír que mis hijos andan en la verdad.', 'familia,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:20', 'Hijos, obedeced a vuestros padres en todo, porque esto agrada al Señor.', 'familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 1:8-9', 'Oye, hijo mío, la instrucción de tu padre, y no desprecies la dirección de tu madre; porque adorno de gracia serán a tu cabeza, y collares a tu cuello.', 'familia,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Timoteo 5:8', 'Porque si alguno no provee para los suyos, y mayormente para los de su casa, ha negado la fe, y es peor que un incrédulo.', 'familia,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 15:20', 'Y levantándose, vino a su padre. Y cuando aún estaba lejos, lo vio su padre, y fue movido a misericordia, y corrió, y se echó sobre su cuello, y le besó.', 'familia,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Tesalonicenses 5:16-18', 'Estad siempre gozosos. Orad sin cesar. Dad gracias en todo, porque esta es la voluntad de Dios para con vosotros en Cristo Jesús.', 'gratitud,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 100:5', 'Porque Jehová es bueno; para siempre es su misericordia, y su verdad por todas las generaciones.', 'gratitud,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 103:1-2', 'Bendice, alma mía, a Jehová, y bendiga todo mi ser su santo nombre. Bendice, alma mía, a Jehová, y no olvides ninguno de sus beneficios.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 103:3-5', 'Él es quien perdona todas tus iniquidades, el que sana todas tus dolencias; el que rescata del hoyo tu vida, el que te corona de favores y misericordias; el que sacia de bien tu boca de modo que te rejuvenezcas como el águila.', 'gratitud,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 107:1', 'Alabad a Jehová, porque él es bueno; porque para siempre es su misericordia.', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 118:1', 'Alabad a Jehová, porque él es bueno; porque para siempre es su misericordia.', 'gratitud,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 9:1', 'Te alabaré, oh Jehová, con todo mi corazón; contaré todas tus maravillas.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 92:1-2', 'Bueno es alabarte, oh Jehová, y cantar salmos a tu nombre, oh Altísimo; anunciar por la mañana tu misericordia, y tu fidelidad cada noche.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 116:12-13', '¿Qué pagaré a Jehová por todos sus beneficios para conmigo? Tomaré la copa de la salvación, e invocaré el nombre de Jehová.', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 2:6-7', 'Por tanto, de la manera que habéis recibido al Señor Jesucristo, andad en él; arraigados y sobreedificados en él, y confirmados en la fe, así como habéis sido enseñados, abundando en acciones de gracias.', 'gratitud,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:17', 'Y todo lo que hacéis, sea de palabra o de hecho, hacedlo todo en el nombre del Señor Jesús, dando gracias a Dios Padre por medio de él.', 'gratitud,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 1:3', 'Bendito sea el Dios y Padre de nuestro Señor Jesucristo, que nos bendijo con toda bendición espiritual en los lugares celestiales en Cristo.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 9:15', '¡Gracias a Dios por su don inefable!', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 1:17', 'Toda buena dádiva y todo don perfecto desciende de lo alto, del Padre de las luces, en el cual no hay mudanza, ni sombra de variación.', 'gratitud,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 16:6', 'Las cuerdas me cayeron en lugares deleitosos, y es hermosa la heredad que me ha tocado.', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 126:3', 'Grandes cosas ha hecho Jehová con nosotros; estaremos alegres.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Crónicas 16:34', 'Aclamad a Jehová, porque él es bueno; porque su misericordia es eterna.', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 7:17', 'Alabaré a Jehová conforme a su justicia, y cantaré al nombre de Jehová el Altísimo.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 30:12', 'Por tanto, a ti cantaré, gloria mía, y no estaré callado. Jehová Dios mío, te alabaré para siempre.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 50:23', 'El que sacrifica alabanza me honrará; y al que ordenare su camino, le mostraré la salvación de Dios.', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 1:3', 'Doy gracias a mi Dios siempre que me acuerdo de vosotros.', 'gratitud,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 12:28', 'Así que, recibiendo nosotros un reino inconmovible, tengamos gratitud, y mediante ella sirvamos a Dios agradándole con temor y reverencia.', 'gratitud,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 68:19', 'Bendito el Señor; cada día nos colma de beneficios el Dios de nuestra salvación.', 'gratitud,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 136:1', 'Alabad a Jehová, porque él es bueno, porque para siempre es su misericordia.', 'gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 103:8', 'Misericordioso y clemente es Jehová; lento para la ira, y grande en misericordia.', 'gratitud,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Jeremías 29:11', 'Porque yo sé los pensamientos que tengo acerca de vosotros, dice Jehová, pensamientos de paz, y no de mal, para daros el fin que esperáis.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 15:13', 'Y el Dios de esperanza os llene de todo gozo y paz en el creer, para que abundéis en esperanza por el poder del Espíritu Santo.', 'esperanza,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 5:5', 'Y la esperanza no avergüenza; porque el amor de Dios ha sido derramado en nuestros corazones por el Espíritu Santo que nos fue dado.', 'esperanza,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:18', 'Pues tengo por cierto que las aflicciones del tiempo presente no son comparables con la gloria venidera que en nosotros ha de manifestarse.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 39:7', 'Y ahora, Señor, ¿qué esperaré? Mi esperanza está en ti.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 62:5-6', 'Alma mía, en Dios solamente reposa, porque de él es mi esperanza. Él solamente es mi roca y mi salvación. Es mi refugio, no resbalaré.', 'esperanza,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 71:5', 'Porque tú, oh Señor Jehová, eres mi esperanza, seguridad mía desde mi juventud.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 130:5', 'Esperé yo a Jehová, esperó mi alma; en su palabra he esperado.', 'esperanza,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lamentaciones 3:25-26', 'Bueno es Jehová a los que en él esperan, al alma que le busca. Bueno es esperar en silencio la salvación de Jehová.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 14:2-3', 'En la casa de mi Padre muchas moradas hay; si así no fuera, yo os lo hubiera dicho; voy, pues, a preparar lugar para vosotros. Y si me fuere y os preparare lugar, vendré otra vez, y os tomaré a mí mismo, para que donde yo estoy, vosotros también estéis.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Apocalipsis 21:4', 'Enjugará Dios toda lágrima de los ojos de ellos; y ya no habrá muerte, ni habrá más llanto, ni clamor, ni dolor; porque las primeras cosas pasaron.', 'esperanza,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Apocalipsis 21:5', 'Y el que estaba sentado en el trono dijo: He aquí, yo hago nuevas todas las cosas. Y me dijo: Escribe; porque estas palabras son fieles y verdaderas.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 1:3', 'Bendito el Dios y Padre de nuestro Señor Jesucristo, que según su grande misericordia nos hizo renacer para una esperanza viva, por la resurrección de Jesucristo de los muertos.', 'esperanza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Tito 2:13', 'Aguardando la esperanza bienaventurada y la manifestación gloriosa de nuestro gran Dios y Salvador Jesucristo.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 6:19', 'La cual tenemos como segura y firme ancla del alma, y que penetra hasta dentro del velo.', 'esperanza,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 3:20', 'Mas nuestra ciudadanía está en los cielos, de donde también esperamos al Salvador, al Señor Jesucristo.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 3:13-14', 'Hermanos, yo mismo no pretendo haberlo ya alcanzado; pero una cosa hago: olvidando ciertamente lo que queda atrás, y extendiéndome a lo que está delante, prosigo a la meta, al premio del supremo llamamiento de Dios en Cristo Jesús.', 'esperanza,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 4:18', 'No mirando nosotros las cosas que se ven, sino las que no se ven; pues las cosas que se ven son temporales, pero las que no se ven son eternas.', 'esperanza,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 2:9', 'Antes bien, como está escrito: Cosas que ojo no vio, ni oído oyó, ni han subido en corazón de hombre, son las que Dios ha preparado para los que le aman.', 'esperanza,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 43:18-19', 'No os acordéis de las cosas pasadas, ni traigáis a memoria las cosas antiguas. He aquí que yo hago cosa nueva; pronto saldrá a luz; ¿no la conoceréis? Otra vez abriré camino en el desierto, y ríos en la soledad.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 23:18', 'Porque ciertamente hay fin, y tu esperanza no será cortada.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:12', 'Gozosos en la esperanza; sufridos en la tribulación; constantes en la oración.', 'esperanza,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 147:11', 'Se complace Jehová en los que le temen, y en los que esperan en su misericordia.', 'esperanza,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 33:20-22', 'Nuestra alma espera a Jehová; nuestra ayuda y nuestro escudo es él. Por tanto, en él se alegrará nuestro corazón, porque en su santo nombre hemos confiado. Sea tu misericordia, oh Jehová, sobre nosotros, según esperamos en ti.', 'esperanza,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 25:8', 'Destruirá a la muerte para siempre; y enjugará Jehová el Señor toda lágrima de todos los rostros; y quitará la afrenta de su pueblo de toda la tierra; porque Jehová lo ha dicho.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Tesalonicenses 4:16-17', 'Porque el Señor mismo con voz de mando, con voz de arcángel, y con trompeta de Dios, descenderá del cielo; y los muertos en Cristo resucitarán primero. Luego nosotros los que vivimos, los que hayamos quedado, seremos arrebatados juntamente con ellos en las nubes para recibir al Señor en el aire, y así estaremos siempre con el Señor.', 'esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 13:4-7', 'El amor es sufrido, es benigno; el amor no tiene envidia, el amor no es jactancioso, no se envanece; no hace nada indebido, no busca lo suyo, no se irrita, no guarda rencor; no se goza de la injusticia, mas se goza de la verdad. Todo lo sufre, todo lo cree, todo lo espera, todo lo soporta.', 'amor,familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 13:13', 'Y ahora permanecen la fe, la esperanza y el amor, estos tres; pero el mayor de ellos es el amor.', 'amor,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 4:7-8', 'Amados, amémonos unos a otros; porque el amor es de Dios. Todo aquel que ama, es nacido de Dios, y conoce a Dios. El que no ama, no ha conocido a Dios; porque Dios es amor.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 4:16', 'Y nosotros hemos conocido y creído el amor que Dios tiene para con nosotros. Dios es amor; y el que permanece en amor, permanece en Dios, y Dios en él.', 'amor,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 4:18', 'En el amor no hay temor, sino que el perfecto amor echa fuera el temor; porque el temor lleva en sí castigo. De donde el que teme, no ha sido perfeccionado en el amor.', 'amor,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 4:19', 'Nosotros le amamos a él, porque él nos amó primero.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 3:1', 'Mirad cuál amor nos ha dado el Padre, para que seamos llamados hijos de Dios; por esto el mundo no nos conoce, porque no le conoció a él.', 'amor,familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 3:18', 'Hijitos míos, no amemos de palabra ni de lengua, sino de hecho y en verdad.', 'amor,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 15:12-13', 'Este es mi mandamiento: Que os améis unos a otros, como yo os he amado. Nadie tiene mayor amor que este, que uno ponga su vida por sus amigos.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 13:34', 'Un mandamiento nuevo os doy: Que os améis unos a otros; como yo os he amado, que también os améis unos a otros.', 'amor,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 5:8', 'Mas Dios muestra su amor para con nosotros, en que siendo aún pecadores, Cristo murió por nosotros.', 'amor,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:10', 'Amaos los unos a los otros con amor fraternal; en cuanto a honra, prefiriéndoos los unos a los otros.', 'amor,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 13:8', 'No debáis a nadie nada, sino el amaros unos a otros; porque el que ama al prójimo, ha cumplido la ley.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Jeremías 31:3', 'Jehová se manifestó a mí hace ya mucho tiempo, diciendo: Con amor eterno te he amado; por tanto, te prolongué mi misericordia.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 22:37-39', 'Jesús le dijo: Amarás al Señor tu Dios con todo tu corazón, y con toda tu alma, y con toda tu mente. Este es el primero y grande mandamiento. Y el segundo es semejante: Amarás a tu prójimo como a ti mismo.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 4:8', 'Y ante todo, tened entre vosotros ferviente amor; porque el amor cubrirá multitud de pecados.', 'amor,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Gálatas 5:22-23', 'Mas el fruto del Espíritu es amor, gozo, paz, paciencia, benignidad, bondad, fe, mansedumbre, templanza; contra tales cosas no hay ley.', 'amor,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 3:17-19', 'Para que habite Cristo por la fe en vuestros corazones, a fin de que, arraigados y cimentados en amor, seáis plenamente capaces de comprender con todos los santos cuál sea la anchura, la longitud, la profundidad y la altura, y de conocer el amor de Cristo, que excede a todo conocimiento, para que seáis llenos de toda la plenitud de Dios.', 'amor,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:14', 'Y sobre todas estas cosas vestíos de amor, que es el vínculo perfecto.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Deuteronomio 7:9', 'Conoce, pues, que Jehová tu Dios es Dios, Dios fiel, que guarda el pacto y la misericordia a los que le aman y guardan sus mandamientos, hasta mil generaciones.', 'amor,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 36:7', '¡Cuán preciosa, oh Dios, es tu misericordia! Por eso los hijos de los hombres se amparan bajo la sombra de tus alas.', 'amor,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 4:2-3', 'Con toda humildad y mansedumbre, soportándoos con paciencia los unos a los otros en amor, solícitos en guardar la unidad del Espíritu en el vínculo de la paz.', 'amor,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 16:14', 'Todas vuestras cosas sean hechas con amor.', 'amor,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 15:9', 'Como el Padre me ha amado, así también yo os he amado; permaneced en mi amor.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 86:15', 'Mas tú, Señor, Dios misericordioso y clemente, lento para la ira, y grande en misericordia y verdad.', 'amor,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 5:2', 'Y andad en amor, como también Cristo nos amó, y se entregó a sí mismo por nosotros, ofrenda y sacrificio a Dios en olor fragante.', 'amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 1:9', 'Si confesamos nuestros pecados, él es fiel y justo para perdonar nuestros pecados, y limpiarnos de toda maldad.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 103:12', 'Cuanto está lejos el oriente del occidente, hizo alejar de nosotros nuestras rebeliones.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 1:18', 'Venid luego, dice Jehová, y estemos a cuenta: si vuestros pecados fueren como la grana, como la nieve serán emblanquecidos; si fueren rojos como el carmesí, vendrán a ser como blanca lana.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Miqueas 7:18-19', '¿Qué Dios como tú, que perdona la maldad, y olvida el pecado del remanente de su heredad? No retuvo para siempre su enojo, porque se deleita en misericordia. Él volverá a tener misericordia de nosotros; sepultará nuestras iniquidades, y echará en lo profundo del mar todos nuestros pecados.', 'perdon,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 4:32', 'Antes sed benignos unos con otros, misericordiosos, perdonándoos unos a otros, como Dios también os perdonó a vosotros en Cristo.', 'perdon,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:13', 'Soportándoos unos a otros, y perdonándoos unos a otros si alguno tuviere queja contra otro. De la manera que Cristo os perdonó, así también hacedlo vosotros.', 'perdon,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 6:14', 'Porque si perdonáis a los hombres sus ofensas, os perdonará también a vosotros vuestro Padre celestial.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 32:1', 'Bienaventurado aquel cuya transgresión ha sido perdonada, y cubierto su pecado.', 'perdon,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 51:10', 'Crea en mí, oh Dios, un corazón limpio, y renueva un espíritu recto dentro de mí.', 'perdon,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 51:12', 'Vuélveme el gozo de tu salvación, y espíritu noble me sustente.', 'perdon,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 5:17', 'De modo que si alguno está en Cristo, nueva criatura es; las cosas viejas pasaron; he aquí todas son hechas nuevas.', 'perdon,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:1', 'Ahora, pues, ninguna condenación hay para los que están en Cristo Jesús, los que no andan conforme a la carne, sino conforme al Espíritu.', 'perdon,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 43:25', 'Yo, yo soy el que borro tus rebeliones por amor de mí mismo, y no me acordaré de tus pecados.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 3:19', 'Así que, arrepentíos y convertíos, para que sean borrados vuestros pecados; para que vengan de la presencia del Señor tiempos de refrigerio.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 86:5', 'Porque tú, Señor, eres bueno y perdonador, y grande en misericordia para con todos los que te invocan.', 'perdon,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 28:13', 'El que encubre sus pecados no prosperará; mas el que los confiesa y se aparta alcanzará misericordia.', 'perdon,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 6:37', 'No juzguéis, y no seréis juzgados; no condenéis, y no seréis condenados; perdonad, y seréis perdonados.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 11:25', 'Y cuando estéis orando, perdonad, si tenéis algo contra alguno, para que también vuestro Padre que está en los cielos os perdone a vosotros vuestras ofensas.', 'perdon,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 8:12', 'Porque seré propicio a sus injusticias, y nunca más me acordaré de sus pecados y de sus iniquidades.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 55:7', 'Deje el impío su camino, y el hombre inicuo sus pensamientos, y vuélvase a Jehová, el cual tendrá de él misericordia, y al Dios nuestro, el cual será amplio en perdonar.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 130:3-4', 'JAH, si mirares a los pecados, ¿quién, oh Señor, podrá mantenerse? Pero en ti hay perdón, para que seas reverenciado.', 'perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 19:10', 'Porque el Hijo del Hombre vino a buscar y a salvar lo que se había perdido.', 'perdon,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 4:19', 'Mi Dios, pues, suplirá todo lo que os falta conforme a sus riquezas en gloria en Cristo Jesús.', 'provision,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 6:33', 'Mas buscad primeramente el reino de Dios y su justicia, y todas estas cosas os serán añadidas.', 'provision,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 6:26', 'Mirad las aves del cielo, que no siembran, ni siegan, ni recogen en graneros; y vuestro Padre celestial las alimenta. ¿No valéis vosotros mucho más que ellas?', 'provision,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 37:25', 'Joven fui, y he envejecido, y no he visto justo desamparado, ni su descendencia que mendigue pan.', 'provision,familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:10', 'Los leoncillos necesitan, y tienen hambre; pero los que buscan a Jehová no tendrán falta de ningún bien.', 'provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 84:11', 'Porque sol y escudo es Jehová Dios; gracia y gloria dará Jehová. No quitará el bien a los que andan en integridad.', 'provision,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 145:15-16', 'Los ojos de todos esperan en ti, y tú les das su comida a su tiempo. Abres tu mano, y colmas de bendición a todo ser viviente.', 'provision,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 3:9-10', 'Honra a Jehová con tus bienes, y con las primicias de todos tus frutos; y serán llenos tus graneros con abundancia, y tus lagares rebosarán de mosto.', 'provision,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Malaquías 3:10', 'Traed todos los diezmos al alfolí y haya alimento en mi casa; y probadme ahora en esto, dice Jehová de los ejércitos, si no os abriré las ventanas de los cielos, y derramaré sobre vosotros bendición hasta que sobreabunde.', 'provision,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 9:6-7', 'Pero esto digo: El que siembra escasamente, también segará escasamente; y el que siembra generosamente, generosamente también segará. Cada uno dé como propuso en su corazón: no con tristeza, ni por necesidad, porque Dios ama al dador alegre.', 'provision,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Corintios 9:8', 'Y poderoso es Dios para hacer que abunde en vosotros toda gracia, a fin de que, teniendo siempre en todas las cosas todo lo suficiente, abundéis para toda buena obra.', 'provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 6:38', 'Dad, y se os dará; medida buena, apretada, remecida y rebosando darán en vuestro regazo; porque con la misma medida con que medís, os volverán a medir.', 'provision,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 11:25', 'El alma generosa será prosperada; y el que saciare, él también será saciado.', 'provision,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Deuteronomio 8:18', 'Sino acuérdate de Jehová tu Dios, porque él te da el poder para hacer las riquezas, a fin de confirmar su pacto que juró a tus padres, como en este día.', 'provision,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 7:11', 'Pues si vosotros, siendo malos, sabéis dar buenas dádivas a vuestros hijos, ¿cuánto más vuestro Padre que está en los cielos dará buenas cosas a los que le pidan?', 'provision,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 10:22', 'La bendición de Jehová es la que enriquece, y no añade tristeza con ella.', 'provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 37:4', 'Deléitate asimismo en Jehová, y él te concederá las peticiones de tu corazón.', 'provision,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:32', 'El que no escatimó ni a su propio Hijo, sino que lo entregó por todos nosotros, ¿cómo no nos dará también con él todas las cosas?', 'provision,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 19:17', 'A Jehová presta el que da al pobre, y el bien que ha hecho, se lo volverá a pagar.', 'provision,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 20:35', 'En todo os he enseñado que, trabajando así, se debe ayudar a los necesitados, y recordar las palabras del Señor Jesús, que dijo: Más bienaventurado es dar que recibir.', 'provision,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 6:11', 'El pan nuestro de cada día, dánoslo hoy.', 'provision,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 58:11', 'Jehová te pastoreará siempre, y en las sequías saciará tu alma, y dará vigor a tus huesos; y serás como huerto de riego, y como manantial de aguas, cuyas aguas nunca faltan.', 'provision,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 65:11', 'Tú coronas el año con tus bienes, y tus nubes destilan grosura.', 'provision,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:23-24', 'Y todo lo que hagáis, hacedlo de corazón, como para el Señor y no para los hombres; sabiendo que del Señor recibiréis la recompensa de la herencia, porque a Cristo el Señor servís.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 10:45', 'Porque el Hijo del Hombre no vino para ser servido, sino para servir, y para dar su vida en rescate por muchos.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 4:10', 'Cada uno según el don que ha recibido, minístrelo a los otros, como buenos administradores de la multiforme gracia de Dios.', 'servicio,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:1', 'Así que, hermanos, os ruego por las misericordias de Dios, que presentéis vuestros cuerpos en sacrificio vivo, santo, agradable a Dios, que es vuestro culto racional.', 'servicio,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:11', 'En lo que requiere diligencia, no perezosos; fervientes en espíritu, sirviendo al Señor.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Gálatas 6:10', 'Así que, según tengamos oportunidad, hagamos bien a todos, y mayormente a los de la familia de la fe.', 'servicio,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 5:16', 'Así alumbre vuestra luz delante de los hombres, para que vean vuestras buenas obras, y glorifiquen a vuestro Padre que está en los cielos.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 25:40', 'Y respondiendo el Rey, les dirá: De cierto os digo que en cuanto lo hicisteis a uno de estos mis hermanos más pequeños, a mí lo hicisteis.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 12:26', 'Si alguno me sirve, sígame; y donde yo estuviere, allí también estará mi servidor. Si alguno me sirviere, mi Padre le honrará.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 13:14-15', 'Pues si yo, el Señor y el Maestro, he lavado vuestros pies, vosotros también debéis lavaros los pies los unos a los otros. Porque ejemplo os he dado, para que como yo os he hecho, vosotros también hagáis.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Josué 22:5', 'Solamente que con diligencia cuidéis de cumplir el mandamiento y la ley que Moisés siervo de Jehová os ordenó: que améis a Jehová vuestro Dios, y andéis en todos sus caminos; que guardéis sus mandamientos, y le sigáis a él, y le sirváis de todo vuestro corazón y de toda vuestra alma.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Samuel 12:24', 'Solamente temed a Jehová y servidle de verdad con todo vuestro corazón, pues considerad cuán grandes cosas ha hecho por vosotros.', 'servicio,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 2:10', 'Porque somos hechura suya, creados en Cristo Jesús para buenas obras, las cuales Dios preparó de antemano para que anduviésemos en ellas.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 6:10', 'Porque Dios no es injusto para olvidar vuestra obra y el trabajo de amor que habéis mostrado hacia su nombre, habiendo ayudado a los santos y ayudándoles aún.', 'servicio,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 2:3-4', 'Nada hagáis por contienda o por vanagloria; antes bien con humildad, estimando cada uno a los demás como superiores a él mismo; no mirando cada uno por lo suyo propio, sino cada cual también por lo de los otros.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Corintios 10:31', 'Si, pues, coméis o bebéis, o hacéis otra cosa, hacedlo todo para la gloria de Dios.', 'servicio,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Timoteo 2:15', 'Procura con diligencia presentarte a Dios aprobado, como obrero que no tiene de qué avergonzarse, que usa bien la palabra de verdad.', 'servicio,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 6:8', 'Después oí la voz del Señor, que decía: ¿A quién enviaré, y quién irá por nosotros? Entonces respondí yo: Heme aquí, envíame a mí.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 28:19-20', 'Por tanto, id, y haced discípulos a todas las naciones, bautizándolos en el nombre del Padre, y del Hijo, y del Espíritu Santo; enseñándoles que guarden todas las cosas que os he mandado; y he aquí yo estoy con vosotros todos los días, hasta el fin del mundo. Amén.', 'servicio,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 16:15', 'Y les dijo: Id por todo el mundo y predicad el evangelio a toda criatura.', 'servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hechos 1:8', 'Pero recibiréis poder, cuando haya venido sobre vosotros el Espíritu Santo, y me seréis testigos en Jerusalén, en toda Judea, en Samaria, y hasta lo último de la tierra.', 'servicio,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 13:16', 'Y de hacer bien y de la ayuda mutua no os olvidéis; porque de tales sacrificios se agrada Dios.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 1:27', 'La religión pura y sin mácula delante de Dios el Padre es esta: Visitar a los huérfanos y a las viudas en sus tribulaciones, y guardarse sin mancha del mundo.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Gálatas 5:13', 'Porque vosotros, hermanos, a libertad fuisteis llamados; solamente que no uséis la libertad como ocasión para la carne, sino servíos por amor los unos a los otros.', 'servicio,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 9:37-38', 'Entonces dijo a sus discípulos: A la verdad la mies es mucha, mas los obreros pocos. Rogad, pues, al Señor de la mies, que envíe obreros a su mies.', 'servicio,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 100:2', 'Servid a Jehová con alegría; venid ante su presencia con regocijo.', 'servicio,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Jeremías 33:3', 'Clama a mí, y yo te responderé, y te enseñaré cosas grandes y ocultas que tú no conoces.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 7:7-8', 'Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá. Porque todo aquel que pide, recibe; y el que busca, halla; y al que llama, se le abrirá.', 'oracion,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Juan 5:14-15', 'Y esta es la confianza que tenemos en él, que si pedimos alguna cosa conforme a su voluntad, él nos oye. Y si sabemos que él nos oye en cualquiera cosa que pidamos, sabemos que tenemos las peticiones que le hayamos hecho.', 'oracion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 5:16', 'Confesaos vuestras ofensas unos a otros, y orad unos por otros, para que seáis sanados. La oración eficaz del justo puede mucho.', 'oracion,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 6:6', 'Mas tú, cuando ores, entra en tu aposento, y cerrada la puerta, ora a tu Padre que está en secreto; y tu Padre que ve en lo secreto te recompensará en público.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 145:18', 'Cercano está Jehová a todos los que le invocan, a todos los que le invocan de veras.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:4', 'Busqué a Jehová, y él me oyó, y me libró de todos mis temores.', 'oracion,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:15', 'Los ojos de Jehová están sobre los justos, y atentos sus oídos al clamor de ellos.', 'oracion,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 55:17', 'Tarde y mañana y a mediodía oraré y clamaré, y él oirá mi voz.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 50:15', 'E invócame en el día de la angustia; te libraré, y tú me honrarás.', 'oracion,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 8:26', 'Y de igual manera el Espíritu nos ayuda en nuestra debilidad; pues qué hemos de pedir como conviene, no lo sabemos, pero el Espíritu mismo intercede por nosotros con gemidos indecibles.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 6:18', 'Orando en todo tiempo con toda oración y súplica en el Espíritu, y velando en ello con toda perseverancia y súplica por todos los santos.', 'oracion,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 4:2', 'Perseverad en la oración, velando en ella con acción de gracias.', 'oracion,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 14:13-14', 'Y todo lo que pidiereis al Padre en mi nombre, lo haré, para que el Padre sea glorificado en el Hijo. Si algo pidiereis en mi nombre, yo lo haré.', 'oracion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 15:7', 'Si permanecéis en mí, y mis palabras permanecen en vosotros, pedid todo lo que queréis, y os será hecho.', 'oracion,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Marcos 1:35', 'Levantándose muy de mañana, siendo aún muy oscuro, salió y se fue a un lugar desierto, y allí oraba.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 18:1', 'También les refirió Jesús una parábola sobre la necesidad de orar siempre, y no desmayar.', 'oracion,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 4:16', 'Acerquémonos, pues, confiadamente al trono de la gracia, para alcanzar misericordia y hallar gracia para el oportuno socorro.', 'oracion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Crónicas 7:14', 'Si se humillare mi pueblo, sobre el cual mi nombre es invocado, y oraren, y buscaren mi rostro, y se convirtieren de sus malos caminos; entonces yo oiré desde los cielos, y perdonaré sus pecados, y sanaré su tierra.', 'oracion,perdon');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 66:19-20', 'Mas ciertamente me escuchó Dios; atendió a la voz de mi súplica. Bendito sea Dios, que no echó de sí mi oración, ni de mí su misericordia.', 'oracion,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 116:1-2', 'Amo a Jehová, pues ha oído mi voz y mis súplicas; porque ha inclinado a mí su oído; por tanto, le invocaré en todos mis días.', 'oracion,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 65:24', 'Y antes que clamen, responderé yo; mientras aún hablan, yo habré oído.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Jeremías 29:12-13', 'Entonces me invocaréis, y vendréis y oraréis a mí, y yo os oiré; y me buscaréis y me hallaréis, porque me buscaréis de todo vuestro corazón.', 'oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 5:3', 'Oh Jehová, de mañana oirás mi voz; de mañana me presentaré delante de ti, y esperaré.', 'oracion,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 26:41', 'Velad y orad, para que no entréis en tentación; el espíritu a la verdad está dispuesto, pero la carne es débil.', 'oracion,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 141:2', 'Suba mi oración delante de ti como el incienso, el don de mis manos como la ofrenda de la tarde.', 'oracion,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 1:5', 'Y si alguno de vosotros tiene falta de sabiduría, pídala a Dios, el cual da a todos abundantemente y sin reproche, y le será dada.', 'sabiduria,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 1:7', 'El principio de la sabiduría es el temor de Jehová; los insensatos desprecian la sabiduría y la enseñanza.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 2:6', 'Porque Jehová da la sabiduría, y de su boca viene el conocimiento y la inteligencia.', 'sabiduria,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 4:23', 'Sobre toda cosa guardada, guarda tu corazón; porque de él mana la vida.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 9:10', 'El temor de Jehová es el principio de la sabiduría, y el conocimiento del Santísimo es la inteligencia.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 16:3', 'Encomienda a Jehová tus obras, y tus pensamientos serán afirmados.', 'sabiduria,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 16:9', 'El corazón del hombre piensa su camino; mas Jehová endereza sus pasos.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 15:1', 'La blanda respuesta quita la ira; mas la palabra áspera hace subir el furor.', 'sabiduria,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 27:17', 'Hierro con hierro se aguza; y así el hombre aguza el rostro de su amigo.', 'sabiduria,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 13:20', 'El que anda con sabios, sabio será; mas el que se junta con necios será quebrantado.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 32:8', 'Te haré entender, y te enseñaré el camino en que debes andar; sobre ti fijaré mis ojos.', 'sabiduria,proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 90:12', 'Enséñanos de tal modo a contar nuestros días, que traigamos al corazón sabiduría.', 'sabiduria,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 30:21', 'Entonces tus oídos oirán a tus espaldas palabra que diga: Este es el camino, andad por él; y no echéis a la mano derecha, ni tampoco torzáis a la mano izquierda.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 1:19', 'Por esto, mis amados hermanos, todo hombre sea pronto para oír, tardo para hablar, tardo para airarse.', 'sabiduria,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 3:17', 'Pero la sabiduría que es de lo alto es primeramente pura, después pacífica, amable, benigna, llena de misericordia y de buenos frutos, sin incertidumbre ni hipocresía.', 'sabiduria,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Colosenses 3:2', 'Poned la mira en las cosas de arriba, no en las de la tierra.', 'sabiduria,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 12:2', 'No os conforméis a este siglo, sino transformaos por medio de la renovación de vuestro entendimiento, para que comprobéis cuál sea la buena voluntad de Dios, agradable y perfecta.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Efesios 5:15-16', 'Mirad, pues, con diligencia cómo andéis, no como necios sino como sabios, aprovechando bien el tiempo, porque los días son malos.', 'sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 19:21', 'Muchos pensamientos hay en el corazón del hombre; mas el consejo de Jehová permanecerá.', 'sabiduria,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Eclesiastés 3:1', 'Todo tiene su tiempo, y todo lo que se quiere debajo del cielo tiene su hora.', 'sabiduria,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Filipenses 4:8', 'Por lo demás, hermanos, todo lo que es verdadero, todo lo honesto, todo lo justo, todo lo puro, todo lo amable, todo lo que es de buen nombre; si hay virtud alguna, si algo digno de alabanza, en esto pensad.', 'sabiduria,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 12:25', 'La congoja en el corazón del hombre lo abate; mas la buena palabra lo alegra.', 'sabiduria,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 17:22', 'El corazón alegre constituye buen remedio; mas el espíritu triste seca los huesos.', 'sabiduria,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Miqueas 6:8', 'Oh hombre, él te ha declarado lo que es bueno, y qué pide Jehová de ti: solamente hacer justicia, y amar misericordia, y humillarte ante tu Dios.', 'sabiduria,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:105', 'Lámpara es a mis pies tu palabra, y lumbrera a mi camino.', 'palabra,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:11', 'En mi corazón he guardado tus dichos, para no pecar contra ti.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:9', '¿Con qué limpiará el joven su camino? Con guardar tu palabra.', 'palabra,familia');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:18', 'Abre mis ojos, y miraré las maravillas de tu ley.', 'palabra,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:103', '¡Cuán dulces son a mi paladar tus palabras! Más que la miel a mi boca.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 1:1-3', 'Bienaventurado el varón que no anduvo en consejo de malos, ni estuvo en camino de pecadores, ni en silla de escarnecedores se ha sentado; sino que en la ley de Jehová está su delicia, y en su ley medita de día y de noche. Será como árbol plantado junto a corrientes de aguas, que da su fruto en su tiempo, y su hoja no cae; y todo lo que hace, prosperará.', 'palabra,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Josué 1:8', 'Nunca se apartará de tu boca este libro de la ley, sino que de día y de noche meditarás en él, para que guardes y hagas conforme a todo lo que en él está escrito; porque entonces harás prosperar tu camino, y todo te saldrá bien.', 'palabra,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Timoteo 3:16-17', 'Toda la Escritura es inspirada por Dios, y útil para enseñar, para redargüir, para corregir, para instruir en justicia, a fin de que el hombre de Dios sea perfecto, enteramente preparado para toda buena obra.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 4:12', 'Porque la palabra de Dios es viva y eficaz, y más cortante que toda espada de dos filos; y penetra hasta partir el alma y el espíritu, las coyunturas y los tuétanos, y discierne los pensamientos y las intenciones del corazón.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 4:4', 'Él respondió y dijo: Escrito está: No sólo de pan vivirá el hombre, sino de toda palabra que sale de la boca de Dios.', 'palabra,provision');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Mateo 24:35', 'El cielo y la tierra pasarán, pero mis palabras no pasarán.', 'palabra,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 55:10-11', 'Porque como desciende de los cielos la lluvia y la nieve, y no vuelve allá, sino que riega la tierra, y la hace germinar y producir, y da semilla al que siembra, y pan al que come, así será mi palabra que sale de mi boca; no volverá a mí vacía, sino que hará lo que yo quiero, y será prosperada en aquello para que la envié.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Romanos 15:4', 'Porque las cosas que se escribieron antes, para nuestra enseñanza se escribieron, a fin de que por la paciencia y la consolación de las Escrituras, tengamos esperanza.', 'palabra,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 1:1', 'En el principio era el Verbo, y el Verbo era con Dios, y el Verbo era Dios.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 8:31-32', 'Dijo entonces Jesús a los judíos que habían creído en él: Si vosotros permaneciereis en mi palabra, seréis verdaderamente mis discípulos; y conoceréis la verdad, y la verdad os hará libres.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Santiago 1:22', 'Pero sed hacedores de la palabra, y no tan solamente oidores, engañándoos a vosotros mismos.', 'palabra,servicio');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Lucas 11:28', 'Y él dijo: Antes bienaventurados los que oyen la palabra de Dios, y la guardan.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 19:7-8', 'La ley de Jehová es perfecta, que convierte el alma; el testimonio de Jehová es fiel, que hace sabio al sencillo. Los mandamientos de Jehová son rectos, que alegran el corazón; el precepto de Jehová es puro, que alumbra los ojos.', 'palabra,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Pedro 2:2', 'Desead, como niños recién nacidos, la leche espiritual no adulterada, para que por ella crezcáis para salvación.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:130', 'La exposición de tus palabras alumbra; hace entender a los simples.', 'palabra,sabiduria');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 6:63', 'El espíritu es el que da vida; la carne para nada aprovecha; las palabras que yo os he hablado son espíritu y son vida.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 40:8', 'Sécase la hierba, marchítase la flor; mas la palabra del Dios nuestro permanece para siempre.', 'palabra,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:89', 'Para siempre, oh Jehová, permanece tu palabra en los cielos.', 'palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 119:50', 'Ella es mi consuelo en mi aflicción, porque tu dicho me ha vivificado.', 'palabra,animo');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 150:6', 'Todo lo que respira alabe a JAH. Aleluya.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 150:1-2', 'Alabad a Dios en su santuario; alabadle en la magnificencia de su firmamento. Alabadle por sus proezas; alabadle conforme a la muchedumbre de su grandeza.', 'alabanza,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:1', 'Bendeciré a Jehová en todo tiempo; su alabanza estará de continuo en mi boca.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 146:1-2', 'Alaba, oh alma mía, a Jehová. Alabaré a Jehová en mi vida; cantaré salmos a mi Dios mientras viva.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 145:3', 'Grande es Jehová, y digno de suprema alabanza; y su grandeza es inescrutable.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 96:1-2', 'Cantad a Jehová cántico nuevo; cantad a Jehová, toda la tierra. Cantad a Jehová, bendecid su nombre; anunciad de día en día su salvación.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 98:4', 'Cantad alegres a Jehová, toda la tierra; levantad la voz, y aplaudid, y cantad salmos.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 100:1', 'Cantad alegres a Dios, habitantes de toda la tierra.', 'alabanza,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 100:3', 'Reconoced que Jehová es Dios; él nos hizo, y no nosotros a nosotros mismos; pueblo suyo somos, y ovejas de su prado.', 'alabanza,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 95:1-2', 'Venid, aclamemos alegremente a Jehová; cantemos con júbilo a la roca de nuestra salvación. Lleguemos ante su presencia con alabanza; aclamémosle con cánticos.', 'alabanza,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 63:3-4', 'Porque mejor es tu misericordia que la vida; mis labios te alabarán. Así te bendeciré en mi vida; en tu nombre alzaré mis manos.', 'alabanza,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 40:3', 'Puso luego en mi boca cántico nuevo, alabanza a nuestro Dios. Verán esto muchos, y temerán, y confiarán en Jehová.', 'alabanza,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 57:9-10', 'Te alabaré entre los pueblos, oh Señor; cantaré de ti entre las naciones. Porque grande es hasta los cielos tu misericordia, y hasta las nubes tu verdad.', 'alabanza,amor');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 86:12', 'Te alabaré, oh Jehová Dios mío, con todo mi corazón, y glorificaré tu nombre para siempre.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 104:33', 'A Jehová cantaré en mi vida; a mi Dios cantaré salmos mientras viva.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 113:3', 'Desde el nacimiento del sol hasta donde se pone, sea alabado el nombre de Jehová.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 147:1', 'Alabad a JAH, porque es bueno cantar salmos a nuestro Dios; porque suave y hermosa es la alabanza.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Hebreos 13:15', 'Así que, ofrezcamos siempre a Dios, por medio de él, sacrificio de alabanza, es decir, fruto de labios que confiesan su nombre.', 'alabanza,gratitud');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Apocalipsis 4:11', 'Señor, digno eres de recibir la gloria y la honra y el poder; porque tú creaste todas las cosas, y por tu voluntad existen y fueron creadas.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Juan 4:23-24', 'Mas la hora viene, y ahora es, cuando los verdaderos adoradores adorarán al Padre en espíritu y en verdad; porque también el Padre tales adoradores busca que le adoren. Dios es Espíritu; y los que le adoran, en espíritu y en verdad es necesario que adoren.', 'alabanza,congregarse');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 8:1', '¡Oh Jehová, Señor nuestro, cuán glorioso es tu nombre en toda la tierra! Has puesto tu gloria sobre los cielos.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 19:1', 'Los cielos cuentan la gloria de Dios, y el firmamento anuncia la obra de sus manos.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 33:1', 'Alegraos, oh justos, en Jehová; en los íntegros es hermosa la alabanza.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 25:1', 'Jehová, tú eres mi Dios; te exaltaré, alabaré tu nombre, porque has hecho maravillas; tus consejos antiguos son verdad y firmeza.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 71:8', 'Sea llena mi boca de tu alabanza, de tu gloria todo el día.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('1 Crónicas 16:23', 'Cantad a Jehová toda la tierra, proclamad de día en día su salvación.', 'alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 16:11', 'Me mostrarás la senda de la vida; en tu presencia hay plenitud de gozo; delicias a tu diestra para siempre.', 'alabanza,esperanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 91:1-2', 'El que habita al abrigo del Altísimo morará bajo la sombra del Omnipotente. Diré yo a Jehová: Esperanza mía, y castillo mío; mi Dios, en quien confiaré.', 'proteccion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 91:4', 'Con sus plumas te cubrirá, y debajo de sus alas estarás seguro; escudo y adarga es su verdad.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 91:11', 'Pues a sus ángeles mandará acerca de ti, que te guarden en todos tus caminos.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 121:7-8', 'Jehová te guardará de todo mal; él guardará tu alma. Jehová guardará tu salida y tu entrada desde ahora y para siempre.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 121:3-4', 'No dará tu pie al resbaladero, ni se dormirá el que te guarda. He aquí, no se adormecerá ni dormirá el que guarda a Israel.', 'proteccion,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Proverbios 18:10', 'Torre fuerte es el nombre de Jehová; a él correrá el justo, y será levantado.', 'proteccion,fuerza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 34:7', 'El ángel de Jehová acampa alrededor de los que le temen, y los defiende.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 32:7', 'Tú eres mi refugio; me guardarás de la angustia; con cánticos de liberación me rodearás.', 'proteccion,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 125:2', 'Como Jerusalén tiene montes alrededor de ella, así Jehová está alrededor de su pueblo desde ahora y para siempre.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Isaías 54:17', 'Ninguna arma forjada contra ti prosperará, y condenarás toda lengua que se levante contra ti en juicio. Esta es la herencia de los siervos de Jehová, y su salvación de mí vendrá, dijo Jehová.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('2 Tesalonicenses 3:3', 'Pero fiel es el Señor, que os afirmará y guardará del mal.', 'proteccion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 61:3', 'Porque tú has sido mi refugio, y torre fuerte delante del enemigo.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Nahúm 1:7', 'Jehová es bueno, fortaleza en el día de la angustia; y conoce a los que en él confían.', 'proteccion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 27:5', 'Porque él me esconderá en su tabernáculo en el día del mal; me ocultará en lo reservado de su morada; sobre una roca me pondrá en alto.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 5:11', 'Pero alégrense todos los que en ti confían; den voces de júbilo para siempre, porque tú los defiendes; en ti se regocijen los que aman tu nombre.', 'proteccion,alabanza');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 17:8', 'Guárdame como a la niña de tus ojos; escóndeme bajo la sombra de tus alas.', 'proteccion,oracion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 16:8', 'A Jehová he puesto siempre delante de mí; porque está a mi diestra, no seré conmovido.', 'proteccion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 9:9-10', 'Jehová será refugio del pobre, refugio para el tiempo de angustia. En ti confiarán los que conocen tu nombre, por cuanto tú, oh Jehová, no desamparaste a los que te buscaron.', 'proteccion,fe');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 46:2-3', 'Por tanto, no temeremos, aunque la tierra sea removida, y se traspasen los montes al corazón del mar; aunque bramen y se turben sus aguas, y tiemblen los montes a causa de su braveza.', 'proteccion,paz');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 138:7', 'Si anduviere yo en medio de la angustia, tú me vivificarás; contra la ira de mis enemigos extenderás tu mano, y me salvará tu diestra.', 'proteccion');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 18:30', 'En cuanto a Dios, perfecto es su camino, y acrisolada la palabra de Jehová; escudo es a todos los que en él esperan.', 'proteccion,palabra');
INSERT INTO versiculos (cita, texto, temas) VALUES ('Salmos 91:9-10', 'Porque has puesto a Jehová, que es mi esperanza, al Altísimo por tu habitación, no te sobrevendrá mal, ni plaga tocará tu morada.', 'proteccion');
